import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BbSdnUwJ.js";const u=JSON.parse('{"title":"Developer onboarding","description":"Set up the compiler for development, run the three test tiers, build this site, and find where a change goes.","frontmatter":{"title":"Developer onboarding","description":"Set up the compiler for development, run the three test tiers, build this site, and find where a change goes."},"headers":[],"relativePath":"development/onboarding.md","filePath":"development/onboarding.md"}'),i={name:"development/onboarding.md"};function n(r,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="developer-onboarding" tabindex="-1">Developer onboarding <a class="header-anchor" href="#developer-onboarding" aria-label="Permalink to &quot;Developer onboarding&quot;">​</a></h1><h2 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental model&quot;">​</a></h2><p>A program describes a robot, world, task, and optional evaluation requirements. The compiler resolves references against explicitly supplied component directories, builds a typed model, derives facts, validates them, and generates target-native files for the user&#39;s installed robot environment. Analysis produces facts; validation judges them without changing the model.</p><p>Read <a href="./architecture.html">Architecture</a> for repository ownership and <a href="./language.html">Language design</a> for program meaning.</p><h2 id="local-setup" tabindex="-1">Local setup <a class="header-anchor" href="#local-setup" aria-label="Permalink to &quot;Local setup&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python -m pip install -e &#39;.[dev]&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pytest</span></span></code></pre></div><p>The compiler is plain Python and needs no ROS, simulator, or Docker installation. Tests have three tiers:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pytest                    # compiler tests; no robot stack</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pytest -m container       # target tools check emitted files</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pytest -m simulation      # execute output and inspect simulator ground truth</span></span></code></pre></div><p>Default test selection excludes the two target tiers. Those require Docker and the target images: <code>robotdsl/ros-gz-nav2:jazzy-harmonic</code> for the Gazebo target (<code>MOBILEDSL_TEST_IMAGE</code> names another) and <code>robotdsl/ros-mujoco-nav2:jazzy</code> for the MuJoCo target (<code>MOBILEDSL_TEST_IMAGE_MUJOCO</code>); see <code>docker/README.md</code> for how the images are built. A tier is skipped when its image is missing. Run container checks for target changes and simulation tests for changes affecting execution. Unit tests alone cannot establish that a robot moves correctly.</p><h2 id="compile-one-program" tabindex="-1">Compile one program <a class="header-anchor" href="#compile-one-program" aria-label="Permalink to &quot;Compile one program&quot;">​</a></h2><p>Supply your program and a local component library:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mobiledsl compile demo.core demo.world demo.task demo.eval --library path/to/parts --check</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mobiledsl compile demo.core demo.world demo.task demo.eval --library path/to/parts \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target ros-gz-nav2 --output out</span></span></code></pre></div><p>The first command validates and reports diagnostics; the second writes one runnable directory whose entry point is <code>out/launch/bringup.launch.py</code>. Libraries are ordinary directories, with no installation or hidden default location. Trace a source expression through its component declaration and emitted files before changing its behavior. Launch the output in your robot environment; compilation does not launch it.</p><h2 id="contribution-paths" tabindex="-1">Contribution paths <a class="header-anchor" href="#contribution-paths" aria-label="Permalink to &quot;Contribution paths&quot;">​</a></h2><p>Paths below are relative to <code>src/mobiledsl/</code>; tests mirror these areas. Import and installation boundary checks live in <code>tests/architecture/</code> at the repo root.</p><table tabindex="0"><thead><tr><th>Change</th><th>Location</th><th>Check</th></tr></thead><tbody><tr><td>Syntax</td><td><code>frontend/</code></td><td>Accepted/rejected input and source spans</td></tr><tr><td>Types and reference resolution</td><td><code>semantic/model/</code>, <code>semantic/lower.py</code></td><td>Entity resolution, units, AST-independent model</td></tr><tr><td>Derived facts</td><td><code>semantic/analysis/</code></td><td>Assembly, requirements, dataflow</td></tr><tr><td>Validation rule</td><td><code>validation/</code></td><td>Pass, fail, and missing evidence</td></tr><tr><td>Library loading</td><td><code>library/</code></td><td>Explicit paths and component references</td></tr><tr><td>Simulator, ROS, or navigation binding</td><td><code>targets/gazebo/</code>, <code>targets/mujoco/</code>, <code>targets/ros2/</code>, <code>targets/nav2/</code></td><td>Native tool checks and simulation</td></tr><tr><td>Target composition</td><td><code>targets/ros_gz_nav2/</code>, <code>targets/ros_mujoco_nav2/</code></td><td>Interfaces agree across generated files</td></tr><tr><td>CLI or compilation workflow</td><td><code>cli.py</code>, <code>driver/</code></td><td>Diagnostics, output boundaries, deterministic files</td></tr></tbody></table><p>Concrete parts belong in component libraries. Keep target formats and runtime imports out of earlier compiler phases; preserve source locations in diagnostics. Compiler tests enforce import boundaries and compilation without ROS or simulator packages. Target tests also run emitted output without the compiler installed.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>This site is built with VitePress from <code>docs/</code>. It needs Node.js 20 or later, and nothing from the compiler:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd docs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm ci</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm run docs:dev      # serve with live reload</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm run docs:build    # the site CI builds, into docs/.vitepress/dist</span></span></code></pre></div><p><code>reference/vocabulary.md</code> and <code>reference/validation.md</code> are generated from the code; edit the vocabulary or the rules and run <code>tools/generate-specs</code>. The test suite fails when a generated page is stale.</p><p>The site is published inside the project site, at <a href="https://mit-cdfg.github.io/robotdsl-site/docs/" target="_blank" rel="noreferrer">https://mit-cdfg.github.io/robotdsl-site/docs/</a>, whose own page is the home the title leads back to; this repository is private, so it has no Pages of its own. To publish, build and copy the output into a checkout of <code>MIT-CDFG/robotdsl-site</code>, replacing the previous build but keeping its <code>docs/release-qa/</code>, then commit and push that repository&#39;s <code>main</code>:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd docs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm run docs:build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rsync -a --delete --exclude release-qa .vitepress/dist/ path/to/robotdsl-site/docs/</span></span></code></pre></div><p>On a network home directory the build can fail while it removes its <code>.vitepress/.temp</code> directory; copy <code>docs/</code> to local disk and build there.</p><h2 id="before-a-pull-request" tabindex="-1">Before a pull request <a class="header-anchor" href="#before-a-pull-request" aria-label="Permalink to &quot;Before a pull request&quot;">​</a></h2><ul><li>Write the user problem, evidence, and owning phase before editing, as required by <code>AGENTS.md</code> in the repository root.</li><li>Add an example with expected output or rejection; run the relevant test tiers and report the commands and results. Missing evidence is not a pass.</li><li>Update affected documentation, inspect the diff, and follow <a href="./contributing.html">Contributing</a> for branch naming and review.</li></ul>`,26)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
